//! Embedded free-amino-acid monomers, generated by scripts/generate_amino_acids.py.
//! GFN2-xTB / ALPB(water), verytight optimization, accuracy 0.1, closed-shell.
//! All entries are checked local minima, not claimed global conformer minima.
//! These are complete monomers: peptide assembly must handle terminal atoms and
//! formal charges explicitly. No runtime files, parsers, xTB, or allocations.
// Static templates shared by the peptide builder and its validation tests.
#![allow(dead_code)]

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AminoAcid {
    Glycine,
    Alanine,
    Valine,
    Leucine,
    Isoleucine,
    Serine,
    Threonine,
    Cysteine,
    Methionine,
    Proline,
    AsparticAcid,
    GlutamicAcid,
    Asparagine,
    Glutamine,
    Histidine,
    Lysine,
    Arginine,
    Phenylalanine,
    Tyrosine,
    Tryptophan,
    Selenocysteine,
    Pyrrolysine,
}
impl AminoAcid {
    pub const ALL: [Self; 22] = [
        Self::Glycine,
        Self::Alanine,
        Self::Valine,
        Self::Leucine,
        Self::Isoleucine,
        Self::Serine,
        Self::Threonine,
        Self::Cysteine,
        Self::Methionine,
        Self::Proline,
        Self::AsparticAcid,
        Self::GlutamicAcid,
        Self::Asparagine,
        Self::Glutamine,
        Self::Histidine,
        Self::Lysine,
        Self::Arginine,
        Self::Phenylalanine,
        Self::Tyrosine,
        Self::Tryptophan,
        Self::Selenocysteine,
        Self::Pyrrolysine,
    ];
    pub const fn name(self) -> &'static str {
        match self {
            Self::Glycine => "Glycine",
            Self::Alanine => "Alanine",
            Self::Valine => "Valine",
            Self::Leucine => "Leucine",
            Self::Isoleucine => "Isoleucine",
            Self::Serine => "Serine",
            Self::Threonine => "Threonine",
            Self::Cysteine => "Cysteine",
            Self::Methionine => "Methionine",
            Self::Proline => "Proline",
            Self::AsparticAcid => "Aspartic Acid",
            Self::GlutamicAcid => "Glutamic Acid",
            Self::Asparagine => "Asparagine",
            Self::Glutamine => "Glutamine",
            Self::Histidine => "Histidine",
            Self::Lysine => "Lysine",
            Self::Arginine => "Arginine",
            Self::Phenylalanine => "Phenylalanine",
            Self::Tyrosine => "Tyrosine",
            Self::Tryptophan => "Tryptophan",
            Self::Selenocysteine => "Selenocysteine",
            Self::Pyrrolysine => "Pyrrolysine",
        }
    }
    pub const fn three_letter(self) -> &'static str {
        match self {
            Self::Glycine => "GLY",
            Self::Alanine => "ALA",
            Self::Valine => "VAL",
            Self::Leucine => "LEU",
            Self::Isoleucine => "ILE",
            Self::Serine => "SER",
            Self::Threonine => "THR",
            Self::Cysteine => "CYS",
            Self::Methionine => "MET",
            Self::Proline => "PRO",
            Self::AsparticAcid => "ASP",
            Self::GlutamicAcid => "GLU",
            Self::Asparagine => "ASN",
            Self::Glutamine => "GLN",
            Self::Histidine => "HIS",
            Self::Lysine => "LYS",
            Self::Arginine => "ARG",
            Self::Phenylalanine => "PHE",
            Self::Tyrosine => "TYR",
            Self::Tryptophan => "TRP",
            Self::Selenocysteine => "SEC",
            Self::Pyrrolysine => "PYL",
        }
    }
    pub const fn one_letter(self) -> char {
        match self {
            Self::Glycine => 'G',
            Self::Alanine => 'A',
            Self::Valine => 'V',
            Self::Leucine => 'L',
            Self::Isoleucine => 'I',
            Self::Serine => 'S',
            Self::Threonine => 'T',
            Self::Cysteine => 'C',
            Self::Methionine => 'M',
            Self::Proline => 'P',
            Self::AsparticAcid => 'D',
            Self::GlutamicAcid => 'E',
            Self::Asparagine => 'N',
            Self::Glutamine => 'Q',
            Self::Histidine => 'H',
            Self::Lysine => 'K',
            Self::Arginine => 'R',
            Self::Phenylalanine => 'F',
            Self::Tyrosine => 'Y',
            Self::Tryptophan => 'W',
            Self::Selenocysteine => 'U',
            Self::Pyrrolysine => 'O',
        }
    }

    pub fn from_one_letter(code: char) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|a| a.one_letter() == code.to_ascii_uppercase())
    }
    pub fn from_three_letter(code: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|a| a.three_letter().eq_ignore_ascii_case(code))
    }
    pub fn templates(self) -> &'static [AminoAcidTemplate] {
        match self {
            Self::Glycine => &TEMPLATES[0..2],
            Self::Alanine => &TEMPLATES[2..4],
            Self::Valine => &TEMPLATES[4..6],
            Self::Leucine => &TEMPLATES[6..8],
            Self::Isoleucine => &TEMPLATES[8..10],
            Self::Serine => &TEMPLATES[10..12],
            Self::Threonine => &TEMPLATES[12..14],
            Self::Cysteine => &TEMPLATES[14..18],
            Self::Methionine => &TEMPLATES[18..20],
            Self::Proline => &TEMPLATES[20..22],
            Self::AsparticAcid => &TEMPLATES[22..26],
            Self::GlutamicAcid => &TEMPLATES[26..30],
            Self::Asparagine => &TEMPLATES[30..32],
            Self::Glutamine => &TEMPLATES[32..34],
            Self::Histidine => &TEMPLATES[34..40],
            Self::Lysine => &TEMPLATES[40..44],
            Self::Arginine => &TEMPLATES[44..48],
            Self::Phenylalanine => &TEMPLATES[48..50],
            Self::Tyrosine => &TEMPLATES[50..54],
            Self::Tryptophan => &TEMPLATES[54..56],
            Self::Selenocysteine => &TEMPLATES[56..60],
            Self::Pyrrolysine => &TEMPLATES[60..62],
        }
    }
    pub fn template(
        self,
        termini: TerminalState,
        side_chain: SideChainState,
    ) -> Option<&'static AminoAcidTemplate> {
        self.templates()
            .iter()
            .find(|t| t.termini == termini && t.side_chain == side_chain)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TerminalState {
    /// Uncharged amino and carboxylic-acid termini; proline has a secondary amine.
    Neutral,
    /// Terminal nitrogen +1 and terminal carboxylate -1. Side chains can add charge.
    Zwitterionic,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SideChainState {
    Neutral,
    Protonated,
    Deprotonated,
    /// Neutral histidine with the ring proton on ND1.
    HistidineDelta,
    /// Neutral histidine with the ring proton on NE2.
    HistidineEpsilon,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BondOrder {
    Single,
    Double,
    Triple,
    Aromatic,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Configuration {
    R,
    S,
}
#[derive(Debug, Clone, Copy)]
pub struct Atom {
    pub name: &'static str,
    pub element: &'static str,
    pub position_angstrom: [f64; 3],
    pub formal_charge: i8,
}
#[derive(Debug, Clone, Copy)]
pub struct Bond {
    pub atoms: [usize; 2],
    pub order: BondOrder,
}
#[derive(Debug, Clone, Copy)]
pub struct Backbone {
    pub nitrogen: usize,
    pub alpha_carbon: usize,
    pub carbonyl_carbon: usize,
    pub carbonyl_oxygen: usize,
    pub terminal_oxygen: usize,
}
#[derive(Debug, Clone, Copy)]
pub struct Stereocenter {
    pub atom: usize,
    pub configuration: Configuration,
    pub neighbours: [usize; 4],
    /// Sign of the oriented tetrahedron in the independent CCD seed geometry.
    pub reference_handedness: i8,
}
#[derive(Debug, Clone, Copy)]
pub struct Optimization {
    pub energy_hartree: f64,
    pub gradient_norm_hartree_per_bohr: f64,
    pub lowest_vibrational_wavenumber_cm1: f64,
    pub vibrational_mode_count: usize,
    pub ccd_sha256: &'static str,
    pub xtb_log_sha256: &'static str,
}
#[derive(Debug)]
pub struct AminoAcidTemplate {
    pub id: &'static str,
    pub amino_acid: AminoAcid,
    pub termini: TerminalState,
    pub side_chain: SideChainState,
    pub formula: &'static str,
    pub charge: i8,
    pub multiplicity: u8,
    pub atoms: &'static [Atom],
    pub bonds: &'static [Bond],
    pub backbone: Backbone,
    pub stereocenters: &'static [Stereocenter],
    pub optimization: Optimization,
}
impl AminoAcidTemplate {
    pub fn atom_index(&self, name: &str) -> Option<usize> {
        self.atoms.iter().position(|a| a.name == name)
    }
}
